package com.rappistream.orderprocessor.infrastructure.health;  import org.apache.kafka.clients.admin.AdminClient; import org.apache.kafka.clients.admin.AdminClientConfig; import org.springframework.boot.actuate.health.Health; import org.springframework.boot.actuate.health.HealthIndicator; import org.springframework.stereotype.Component;  import java.time.Duration; import java.util.Map; import java.util.Properties; import java.util.concurrent.TimeUnit;  @Component("kafka") public class KafkaHealthIndicator implements HealthIndicator {      private final String bootstrapServers;      public KafkaHealthIndicator(@org.springframework.beans.factory.annotation.Value("${spring.kafka.bootstrap-servers}") String bootstrapServers) {         this.bootstrapServers = bootstrapServers;     }      @Override     public Health health() {         Properties props = new Properties();         props.put(AdminClientConfig.BOOTSTRAP_SERVERS_CONFIG, bootstrapServers);         try (AdminClient admin = AdminClient.create(props)) {             admin.describeCluster().clusterId().get(5, TimeUnit.SECONDS);             return Health.up().build();         } catch (Exception e) {             return Health.down(e).build();         }     } }
